<template>
  <dialog ref="dialog" class="pdf-export-dialog move-device-dialog" aria-labelledby="move-device-title"><div class="pdf-export-dialog-header"><div><p class="eyebrow">REASSIGN DEVICE</p><h3 id="move-device-title">Move {{ deviceName || 'device' }} to another subnet</h3></div><button class="pdf-dialog-close" type="button" aria-label="Close move-device dialog" @click="close">×</button></div><p class="pdf-export-description">The complete device configuration, relationships, and IDs will be preserved. Local addresses follow the device without changing their values.</p><div class="form-group"><label for="move-device-target">Destination subnet</label><select id="move-device-target" :value="targetId" @change="$emit('update:targetId', ($event.target as HTMLSelectElement).value)"><option v-for="target in targets" :key="target.id" :value="target.id">{{ target.name || 'Unnamed subnet' }} — {{ subnetLabel(target) }}</option></select><span class="field-hint">Addresses outside the destination prefix will be flagged for correction.</span></div><div class="pdf-export-dialog-actions"><AppButton @click="close">Cancel</AppButton><AppButton variant="primary" :disabled="!targetId" @click="$emit('confirm')">Move device</AppButton></div></dialog>
</template>
<script setup lang="ts">
import { ref } from 'vue'; import AppButton from '../../AppButton.vue'; import type { DiagramSubnet } from '../../../lib/network-diagram';
defineProps<{ deviceName?: string; targetId: string; targets: DiagramSubnet[]; subnetLabel: (subnet: DiagramSubnet) => string }>(); defineEmits<{ 'update:targetId': [value: string]; confirm: [] }>();
const dialog = ref<HTMLDialogElement | null>(null); function open() { dialog.value?.showModal(); } function close() { dialog.value?.close(); } defineExpose({ open, close });
</script>
